const respuesta = $input.first().json;
const updates = respuesta.result || [];

if (updates.length === 0) {
  return [];
}

const ultimo_update_id = updates[updates.length - 1].update_id;

const items = [];
for (const update of updates) {
  if (update.message) {
    items.push({
      json: {
        message: update.message,
        ultimo_update_id: ultimo_update_id
      }
    });
  }
}

return items;

const mensaje = $('Procesar Updates').first().json.message;

const chat_id = mensaje.chat.id;
const texto = mensaje.text || mensaje.caption || "";
const nombre_usuario = mensaje.from.first_name || "Usuario";

let tiene_archivo = false;
let file_id = "";
let nombre_archivo = "";

if (mensaje.document) {
  tiene_archivo = true;
  file_id = mensaje.document.file_id;
  nombre_archivo = mensaje.document.file_name || "documento";
}

return [{
  json: {
    chat_id: chat_id,
    texto_usuario: texto,
    nombre_usuario: nombre_usuario,
    tiene_archivo: tiene_archivo,
    file_id: file_id,
    nombre_archivo: nombre_archivo
  }
}];

const texto_usuario = $('Extraer Info Mensaje').first().json.texto_usuario;
const nombre_archivo = $('Extraer Info Mensaje').first().json.nombre_archivo;
const contenido = ($input.first().json.text || "").slice(0, 4000);

const nombre_limpio = nombre_archivo
  .replace(/\.pdf$/i, "")
  .replace(/[_-]/g, " ");

const texto_para_rag = texto_usuario + " " + nombre_limpio + " contenido temas ejercicios definiciones";

return [{
  json: {
    texto_para_rag: texto_para_rag,
    texto_usuario: texto_usuario + ` [Archivo adjunto: ${nombre_archivo}]` + (contenido ? `\n\nContenido del archivo:\n${contenido}` : ""),
    archivo_descargado: true
  }
}];

const items = $input.all();
const datos = items[0].json;

let texto_para_rag = "";
let texto_usuario = "";

if (datos.texto_para_rag) {
  texto_para_rag = datos.texto_para_rag;
  texto_usuario = datos.texto_usuario;
} else {
  texto_para_rag = datos.texto_usuario;
  texto_usuario = datos.texto_usuario;
}

const chat_id = $('Extraer Info Mensaje').first().json.chat_id;
const nombre_usuario = $('Extraer Info Mensaje').first().json.nombre_usuario;

return [{
  json: {
    chat_id: chat_id,
    nombre_usuario: nombre_usuario,
    texto_usuario: texto_usuario,
    texto_para_rag: texto_para_rag
  }
}];

const items = $input.all();
const embedding = $('Embedding Pregunta').first().json.embedding;
const tipos = $('Leer Orquestador').first().json.tipos;
let coleccionId = "";

for (const item of items) {
  if (item.json.name === ($env.COLECCION || "tutorias")) {
    coleccionId = item.json.id;
    break;
  }
}

return [{
  json: {
    coleccion_id: coleccionId,
    query_body: {
      query_embeddings: [embedding],
      n_results: 5,
      include: ["documents", "metadatas", "distances"],
      ...(tipos ? { where: { tipo: { $in: tipos } } } : {})
    }
  }
}];

const resultados = $input.first().json;
const documentos = resultados.documents[0];
const metadatos = resultados.metadatas[0];
const distancias = resultados.distances[0];

let partes = [];
for (let i = 0; i < documentos.length; i++) {
  const similitud = (1 - distancias[i]).toFixed(3);
  const archivo = metadatos[i].archivo;
  const pagina = metadatos[i].pagina;
  partes.push(`[Fuente: ${archivo}, p.${pagina} | Similitud: ${similitud}]\n${documentos[i]}`);
}

return [{
  json: {
    contexto_rag: partes.join("\n\n---\n\n"),
    num_fragmentos: documentos.length,
    fuentes: metadatos.map(m => ({ archivo: m.archivo, pagina: m.pagina }))
  }
}];

const orquestador = $('Leer Orquestador').first().json;
const respuesta_cruda = $input.first().json.message.content;
const chat_id = orquestador.chat_id;
const nombre_usuario = orquestador.nombre_usuario;
const DIAS = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"];

// El LLM escribe \frac sin escapar y en JSON llega como salto de página + "rac"
function corregirLatex(valor) {
  if (Array.isArray(valor)) return valor.map(corregirLatex);
  if (valor && typeof valor === "object") {
    return Object.fromEntries(Object.entries(valor).map(([k, v]) => [k, corregirLatex(v)]));
  }
  if (typeof valor !== "string") return valor;
  return valor
    .replace(/\f/g, "\\f").replace(/\t/g, "\\t").replace(/\x08/g, "\\b").replace(/\r/g, "\\r")
    .replace(/\n(?=(eq|u\b|abla|ot\b|eg\b|ewline|leq|geq))/g, "\\n");
}

// Próxima fecha con ese día de la semana; nunca hoy (para hoy se dice "hoy")
function proximo(dia) {
  const hoy = DateTime.now().setZone("America/Bogota").startOf("day");
  return hoy.plus({ days: (DIAS.indexOf(dia) - hoy.weekday + 7) % 7 + 1 }).toISODate();
}

let json_parseado = null;
let error_parseo = false;
let fue_reparado = false;

try {
  let texto_limpio = respuesta_cruda.trim();

  if (texto_limpio.startsWith("```json")) {
    texto_limpio = texto_limpio.replace(/```json\s*/g, "").replace(/```\s*/g, "");
  }
  if (texto_limpio.startsWith("```")) {
    texto_limpio = texto_limpio.replace(/```\s*/g, "");
  }

  const inicio = texto_limpio.indexOf("{");
  const fin = texto_limpio.lastIndexOf("}");
  if (inicio !== -1 && fin !== -1 && fin > inicio) {
    texto_limpio = texto_limpio.substring(inicio, fin + 1);
  }

  json_parseado = JSON.parse(texto_limpio);
} catch (e) {
  let texto_reparar = respuesta_cruda.trim();
  const inicio = texto_reparar.indexOf("{");
  if (inicio !== -1) {
    texto_reparar = texto_reparar.substring(inicio);
  }

  let brackets_abiertos = 0;
  let corchetes_abiertos = 0;
  let en_string = false;
  let escape = false;

  for (let i = 0; i < texto_reparar.length; i++) {
    const c = texto_reparar[i];
    if (escape) { escape = false; continue; }
    if (c === '\\') { escape = true; continue; }
    if (c === '"') { en_string = !en_string; continue; }
    if (en_string) continue;
    if (c === '{') brackets_abiertos++;
    if (c === '}') brackets_abiertos--;
    if (c === '[') corchetes_abiertos++;
    if (c === ']') corchetes_abiertos--;
  }

  let cierre = "";
  for (let i = 0; i < corchetes_abiertos; i++) cierre += "]";
  for (let i = 0; i < brackets_abiertos; i++) cierre += "}";

  if (en_string) {
    texto_reparar += '"';
  }

  texto_reparar += cierre;

  try {
    json_parseado = JSON.parse(texto_reparar);
    fue_reparado = true;
  } catch (e2) {
    error_parseo = true;
  }
}

if (error_parseo || !json_parseado) {
  return [{
    json: {
      tarea: "error_parseo",
      chat_id: chat_id,
      nombre_usuario: nombre_usuario,
      respuesta_cruda: respuesta_cruda
    }
  }];
}

json_parseado = corregirLatex(json_parseado);
json_parseado.tarea = orquestador.tarea;
json_parseado.chat_id = chat_id;
json_parseado.nombre_usuario = nombre_usuario;
json_parseado.fue_reparado = fue_reparado;
json_parseado.fuentes = $('Formatear Contexto RAG').isExecuted ? $('Formatear Contexto RAG').first().json.fuentes : [];

if (DIAS.includes(json_parseado.dia_semana)) {
  json_parseado.fecha = proximo(json_parseado.dia_semana);
}

return [{
  json: json_parseado
}];

const datos = $input.first().json;
const sesiones = datos.sesiones || [];

let mensaje = `📚 *Plan de Clases*\nNivel: ${datos.nivel || "universidad"}\n`;
for (const sesion of sesiones) {
  mensaje += `\n📖 Sesión ${sesion.numero}: ${sesion.titulo} (${sesion.duracion_minutos} min)`;
}
mensaje += `\n\n📄 _Enviando PDF con el plan completo..._`;

if (datos.fue_reparado) {
  mensaje += `\n\n⚠️ _Nota: La respuesta fue truncada. Algunas sesiones pueden estar incompletas._`;
}

const fuentes = [...new Set((datos.fuentes || []).map(f => `\`${f.archivo} p.${f.pagina}\``))];
if (fuentes.length > 0) {
  mensaje += `\n\n📚 Basado en: ${fuentes.join(" · ")}`;
}

return [{
  json: {
    chat_id: datos.chat_id,
    mensaje: mensaje,
    datos_plan: {
      nivel: datos.nivel,
      prerequisitos: datos.prerequisitos,
      sesiones: sesiones
    }
  }
}];

const datos = $input.first().json;
const temas = datos.temas || [];
const nivel = datos.nivel || "universidad";

let mensaje = `📝 *Banco de Ejercicios*\nNivel: ${nivel}\n`;
let total_ejercicios = 0;

for (const tema of temas) {
  mensaje += `\n━━━━━━━━━━━━━━━━━━\n`;
  mensaje += `*Tema: ${tema.nombre}*\n`;

  const ejercicios = tema.ejercicios || [];
  total_ejercicios += ejercicios.length;

  for (const ej of ejercicios) {
    const icono = ej.nivel_dificultad === "facil" ? "🟢" :
                  ej.nivel_dificultad === "media" ? "🟡" : "🔴";
    mensaje += `${icono} ${ej.nivel_dificultad} — ${ej.enunciado.substring(0, 100)}...\n`;
  }
}

mensaje += `\n📄 _Enviando PDF con ${total_ejercicios} ejercicios y soluciones completas..._`;

const fuentes = [...new Set((datos.fuentes || []).map(f => `\`${f.archivo} p.${f.pagina}\``))];
if (fuentes.length > 0) {
  mensaje += `\n\n📚 Basado en: ${fuentes.join(" · ")}`;
}

return [{
  json: {
    chat_id: datos.chat_id,
    mensaje: mensaje,
    datos_ejercicios: {
      nivel: datos.nivel,
      temas: datos.temas
    }
  }
}];

const datos = $input.first().json;

return [{
  json: {
    chat_id: datos.chat_id,
    mensaje: `❓ ${datos.mensaje}`
  }
}];

const datos = $input.first().json;

let mensaje = "⚠️ No pude procesar tu solicitud correctamente. Por favor intenta reformular tu mensaje.";

if (datos.tarea === "error_parseo") {
  mensaje += "\n\n_Detalle técnico: la respuesta del modelo no fue JSON válido._";
}

return [{
  json: {
    chat_id: datos.chat_id || "",
    mensaje: mensaje
  }
}];

const chat_id = $input.first().json.chat_id;
const mensaje_completo = $input.first().json.mensaje;

const LIMITE = 4000;
const mensajes = [];

if (mensaje_completo.length <= LIMITE) {
  mensajes.push(mensaje_completo);
} else {
  let restante = mensaje_completo;
  while (restante.length > 0) {
    if (restante.length <= LIMITE) {
      mensajes.push(restante);
      break;
    }
    let corte = restante.lastIndexOf("\n", LIMITE);
    if (corte === -1 || corte < LIMITE * 0.5) {
      corte = LIMITE;
    }
    mensajes.push(restante.substring(0, corte));
    restante = restante.substring(corte).trimStart();
  }
}

const items = mensajes.map(msg => ({
  json: {
    chat_id: chat_id,
    texto: msg
  }
}));

return items;

const datos = $input.first().json;

const estudiante = datos.estudiante || "";
const fecha = datos.fecha || "";
const hora_inicio = datos.hora_inicio || "";
const hora_fin = datos.hora_fin || "";
const modalidad = datos.modalidad || "";

let errores = [];

if (!estudiante || estudiante === "Nombre") {
  errores.push("nombre del estudiante");
}

const fecha_regex = /^\d{4}-\d{2}-\d{2}$/;
if (!fecha || !fecha_regex.test(fecha)) {
  errores.push("fecha en formato YYYY-MM-DD");
}

const hora_regex = /^\d{2}:\d{2}$/;
if (!hora_inicio || !hora_regex.test(hora_inicio)) {
  errores.push("hora de inicio en formato HH:MM");
}

const modalidad_asumida = modalidad !== "virtual" && modalidad !== "presencial";

let hora_fin_final = hora_fin;
if (!hora_fin || !hora_regex.test(hora_fin)) {
  if (hora_inicio && hora_regex.test(hora_inicio)) {
    const partes = hora_inicio.split(":");
    let hora = parseInt(partes[0]) + 1;
    if (hora > 23) hora = 23;
    hora_fin_final = String(hora).padStart(2, '0') + ":" + partes[1];
  }
}

if (errores.length > 0) {
  return [{
    json: {
      valido: false,
      chat_id: datos.chat_id,
      mensaje_error: `Para agendar la clase necesito que especifiques: ${errores.join(", ")}.`
    }
  }];
}

const fecha_inicio_iso = `${fecha}T${hora_inicio}:00`;
const fecha_fin_iso = `${fecha}T${hora_fin_final}:00`;

return [{
  json: {
    valido: true,
    chat_id: datos.chat_id,
    nombre_usuario: datos.nombre_usuario,
    estudiante: estudiante,
    fecha: fecha,
    hora_inicio: hora_inicio,
    hora_fin: hora_fin_final,
    modalidad: modalidad_asumida ? "virtual" : modalidad,
    modalidad_asumida: modalidad_asumida,
    notas: datos.notas || "",
    fecha_inicio_iso: fecha_inicio_iso,
    fecha_fin_iso: fecha_fin_iso,
    confirmacion: datos.confirmacion || ""
  }
}];

const datos = $input.first().json;

return [{
  json: {
    chat_id: datos.chat_id,
    mensaje: `❓ ${datos.mensaje_error}\n\nEjemplo: "Planea una clase con María el lunes 24 de marzo a las 2pm, virtual"`
  }
}];

const evento = $input.first().json;
const datos_clase = $('Validar Datos Clase').first().json;

const estudiante = datos_clase.estudiante;
const fecha = datos_clase.fecha;
const hora_inicio = datos_clase.hora_inicio;
const hora_fin = datos_clase.hora_fin;
const modalidad = datos_clase.modalidad;
const notas = datos_clase.notas;
const chat_id = datos_clase.chat_id;

let meet_link = "";
if (evento.conferenceData && evento.conferenceData.entryPoints) {
  for (const ep of evento.conferenceData.entryPoints) {
    if (ep.entryPointType === "video") {
      meet_link = ep.uri;
      break;
    }
  }
}
if (!meet_link && evento.hangoutLink) {
  meet_link = evento.hangoutLink;
}

let mensaje = `✅ *Clase Agendada Exitosamente*\n\n`;
mensaje += `👤 *Estudiante:* ${estudiante}\n`;
mensaje += `📆 *Fecha:* ${fecha}\n`;
mensaje += `🕐 *Hora:* ${hora_inicio} - ${hora_fin}\n`;
mensaje += `📍 *Modalidad:* ${modalidad}${datos_clase.modalidad_asumida ? " (asumida)" : ""}\n`;

if (notas) {
  mensaje += `📝 *Notas:* ${notas}\n`;
}

if (meet_link) {
  mensaje += `\n🔗 *Enlace Google Meet:*\n${meet_link}\n`;
  mensaje += `\n_Comparte este enlace con ${estudiante} antes de la clase._`;
} else if (modalidad === "virtual") {
  mensaje += `\n⚠️ _No se pudo generar el enlace de Meet automáticamente. Créalo manualmente desde Google Calendar._`;
}

if (evento.htmlLink) {
  mensaje += `\n\n📅 [Ver en Google Calendar](${evento.htmlLink})`;
}

return [{
  json: {
    chat_id: chat_id,
    mensaje: mensaje
  }
}];

const datos = $input.first().json;

const sistema = `Eres el enrutador de un asistente para un tutor privado de matemáticas y estadística.
Lee el mensaje del tutor y elige la tarea:

- plan_de_clases: pide un plan, programa, planificación o secuencia de sesiones para enseñar temas.
- banco_de_ejercicios: pide ejercicios, problemas, talleres o evaluaciones.
- planificar_clase: pide agendar, programar o reservar una clase con alguien en una fecha u hora.
- aclarar: no se puede saber qué quiere.

En "consulta" escribe una búsqueda corta solo con los temas que el tutor menciona, sin añadir conceptos que no pidió
y sin palabras como "plan", "sesiones" o "ejercicios".
Ejemplos: "distribución de Poisson" · "intervalo de confianza para la media con varianza desconocida".
Deja "consulta" vacía si la tarea es planificar_clase o aclarar.

En "mensaje" escribe una pregunta breve y específica solo si la tarea es aclarar; en otro caso déjalo vacío.`;

const esquema = {
  type: "object",
  required: ["tarea", "consulta", "mensaje"],
  properties: {
    tarea: { enum: ["plan_de_clases", "banco_de_ejercicios", "planificar_clase", "aclarar"] },
    consulta: { type: "string" },
    mensaje: { type: "string" }
  }
};

return [{
  json: {
    ollama_body_string: JSON.stringify({
      model: $env.LLM_MODEL || "qwen3:14b",
      messages: [
        { role: "system", content: sistema },
        { role: "user", content: datos.texto_usuario }
      ],
      stream: false,
      think: false,
      format: esquema,
      options: { temperature: 0, num_ctx: 8192, num_predict: 512 }
    })
  }
}];

const datos = $('Normalizar Datos').first().json;
const orquestador = JSON.parse($input.first().json.message.content);
const tarea = orquestador.tarea;

return [{
  json: {
    chat_id: datos.chat_id,
    nombre_usuario: datos.nombre_usuario,
    texto_usuario: datos.texto_usuario,
    tarea: tarea,
    consulta: orquestador.consulta,
    mensaje: orquestador.mensaje || "¿Podrías darme más detalles de lo que necesitas?",
    tipos: tarea === "banco_de_ejercicios" ? ["ejercicios", "evaluacion"] : null,
    necesita_rag: (tarea === "plan_de_clases" || tarea === "banco_de_ejercicios") && orquestador.consulta !== ""
  }
}];

const orquestador = $('Leer Orquestador').first().json;
const contexto = $json.contexto_rag ? `\n\nMATERIAL DEL TUTOR:\n\n${$json.contexto_rag}` : "";
const TEXTO = { type: "string" };
const LISTA = { type: "array", items: TEXTO };
const NIVEL = { enum: ["secundaria", "universidad", "posgrado"] };
const objeto = (campos) => ({ type: "object", required: Object.keys(campos), properties: campos });

const sistema = `Eres el asistente de un tutor privado de matemáticas y estadística. Sus estudiantes son de secundaria, universidad y posgrado; si no se indica el nivel, asume universidad.

Diseña un plan de clases:
- Objetivos con verbos de Bloom: identificar, explicar, aplicar, analizar, evaluar, crear.
- La explicación debe servirle al tutor para recordar lo esencial: definiciones, fórmulas clave y un ejemplo numérico concreto.
- En recomendaciones didácticas incluye errores comunes de los estudiantes, analogías útiles y el orden sugerido.
- Fórmulas en LaTeX entre $...$.

Si hay MATERIAL DEL TUTOR, úsalo como base: refleja el enfoque, la notación y los ejemplos que usa en sus tutorías.` + contexto;

const esquema = objeto({
  nivel: NIVEL,
  prerequisitos: TEXTO,
  sesiones: {
    type: "array", minItems: 1, items: objeto({
      numero: { type: "integer" }, titulo: TEXTO, temas: LISTA, objetivos: LISTA,
      explicacion: TEXTO, recomendaciones_didacticas: TEXTO, duracion_minutos: { type: "integer" }
    })
  }
});

return [{
  json: {
    ollama_body_string: JSON.stringify({
      model: $env.LLM_MODEL || "qwen3:14b",
      messages: [
        { role: "system", content: sistema },
        { role: "user", content: orquestador.texto_usuario }
      ],
      stream: false,
      think: false,
      format: esquema,
      options: { temperature: 0.2, num_ctx: 8192, num_predict: 4096 }
    })
  }
}];

const orquestador = $('Leer Orquestador').first().json;
const contexto = $json.contexto_rag ? `\n\nMATERIAL DEL TUTOR:\n\n${$json.contexto_rag}` : "";
const TEXTO = { type: "string" };
const LISTA = { type: "array", items: TEXTO };
const NIVEL = { enum: ["secundaria", "universidad", "posgrado"] };
const objeto = (campos) => ({ type: "object", required: Object.keys(campos), properties: campos });

const sistema = `Eres el asistente de un tutor privado de matemáticas y estadística. Sus estudiantes son de secundaria, universidad y posgrado; si no se indica el nivel, asume universidad.

Crea un banco de ejercicios:
- Cada tema incluye los tres niveles de dificultad (facil, media, dificil), salvo que el tutor pida solo algunos.
- Cantidad por nivel: la que indique el tutor ("1 por nivel" = 1 facil + 1 media + 1 dificil); si no indica, 2 por nivel.
- Si el tutor pide un número total ("1 ejercicio fácil"), genera exactamente eso.
- nivel es el nivel académico, no la dificultad: si el tutor no escribe "secundaria" o "posgrado", nivel = universidad. La dificultad debe ser coherente con ese nivel.
- Enunciados con datos concretos y contexto realista.
- Solución paso a paso con el resultado numérico final.
- En notas pedagógicas: el error común que el ejercicio pone a prueba.
- Toda expresión matemática en LaTeX entre $...$.

Si hay MATERIAL DEL TUTOR, inspírate en el estilo, contextos y notación de sus talleres, sin copiarlos literalmente.` + contexto;

const esquema = objeto({
  nivel: NIVEL,
  temas: {
    type: "array", minItems: 1, items: objeto({
      nombre: TEXTO,
      ejercicios: {
        type: "array", minItems: 1, items: objeto({
          nivel_dificultad: { enum: ["facil", "media", "dificil"] },
          enunciado: TEXTO, solucion: TEXTO, notas_pedagogicas: TEXTO
        })
      }
    })
  }
});

return [{
  json: {
    ollama_body_string: JSON.stringify({
      model: $env.LLM_MODEL || "qwen3:14b",
      messages: [
        { role: "system", content: sistema },
        { role: "user", content: orquestador.texto_usuario }
      ],
      stream: false,
      think: false,
      format: esquema,
      options: { temperature: 0.2, num_ctx: 8192, num_predict: 4096 }
    })
  }
}];

const orquestador = $('Leer Orquestador').first().json;
const DIAS = ["lunes", "martes", "miércoles", "jueves", "viernes", "sábado", "domingo"];
const TEXTO = { type: "string" };

const hoy = DateTime.now().setZone("America/Bogota").startOf("day");
const calendario = Array.from({ length: 14 }, (_, i) => {
  const dia = hoy.plus({ days: i });
  return `- ${DIAS[dia.weekday - 1]} ${dia.toISODate()}` + (i === 0 ? " (hoy)" : "");
}).join("\n");

const sistema = `Extrae los datos para agendar una clase de tutoría.
Zona horaria America/Bogota. Calendario de los próximos días:
${calendario}

- dia_semana: si el tutor nombra un día de la semana ("el miércoles", "el próximo viernes"), ese día en minúsculas; si no, vacío.
- fecha en formato AAAA-MM-DD, tomada del calendario, cuando el tutor da una fecha o dice hoy, mañana o pasado mañana.
- hora_inicio y hora_fin en formato 24 h HH:MM; si no se indica la hora de fin, suma 1 hora.
- modalidad: virtual, presencial o no_indicada si el tutor no la menciona.
- estudiante: el nombre tal como lo escribe el tutor; vacío si no lo dice.
- confirmacion: una frase legible con el resumen de la clase.`;

const esquema = {
  type: "object",
  required: ["estudiante", "dia_semana", "fecha", "hora_inicio", "hora_fin", "modalidad", "notas", "confirmacion"],
  properties: {
    estudiante: TEXTO, dia_semana: { enum: [...DIAS, ""] }, fecha: TEXTO, hora_inicio: TEXTO, hora_fin: TEXTO,
    modalidad: { enum: ["virtual", "presencial", "no_indicada"] }, notas: TEXTO, confirmacion: TEXTO
  }
};

return [{
  json: {
    ollama_body_string: JSON.stringify({
      model: $env.LLM_MODEL || "qwen3:14b",
      messages: [
        { role: "system", content: sistema },
        { role: "user", content: orquestador.texto_usuario }
      ],
      stream: false,
      think: false,
      format: esquema,
      options: { temperature: 0, num_ctx: 8192, num_predict: 4096 }
    })
  }
}];
